#include "runtime/MeshExperimentJob.h"
#include <iostream>
#include <cmath>
#include <stdexcept>
using namespace spacerad::engine;
int count=0;void check(bool b,const char* m){++count;if(!b)throw std::runtime_error(m);}
MeshExperimentJob parse(const Json& j){return parseMeshExperiment(QByteArray::fromStdString(j.dump()));}
bool rejects(const Json& j){try{parse(j);return false;}catch(const std::exception&){return true;}}
int main(){try{
    auto demo=meshExperimentDemo();auto a=parse(demo);check(a.mesh.report.at("geometry_gate_passed")==true,"valid convex box");check(a.mesh.report.at("transport_allowed")==false,"legacy mesh review remains review-only");check(a.source.synthetic&&a.source.quantity==SpectrumQuantity::Fluence,"synthetic fluence contract");check(std::abs(a.source.integratedSpectrum()-1e7)<1e-7,"uniform fluence integral");check(std::abs(a.source.expectedPrimaries()-pi*9e7)<1e-5,"isotropic sphere normalization");check(a.source.spectra[0].sample(.5)==1.5,"uniform energy sampling");check(parse(meshExperimentDemo("proton")).source.spectra[0].sample(.5)==15,"proton interval");
    auto j=demo;j["solid"]="analytic_box_reference";check(parse(j).analyticReference,"exact box comparator");j=demo;j["mesh"]["part"]["center"]={2,3,4};j["mesh"]["part"]["rotation_deg"]={10,20,30};check(parse(j).mesh.placement.translation==Vector3{2,3,4},"placement retained independently of source scaffold");
    j=demo;j["source"]["synthetic"]=false;check(rejects(j),"non-synthetic source rejected");j=demo;j["source"]["synthetic"]=1;check(rejects(j),"boolean strict");j=demo;j["source"]["particle"]="alpha";check(rejects(j),"unsupported particle");j=demo;j["source"]["energy_max_MeV"]=1;check(rejects(j),"zero width energy");j=demo;j["source"]["omnidirectional_fluence_cm2"]=-1;check(rejects(j),"negative fluence");j=demo;j["run"]["histories"]=2.5;check(rejects(j),"fractional histories");j=demo;j["run"]["seed"]=0;check(rejects(j),"invalid seed");j=demo;j["run"]["source_radius_mm"]=10;check(rejects(j),"source must enclose mesh");j=demo;j["run"]["source_radius_mm"]="30";check(rejects(j),"numeric strings rejected");j=demo;j["mesh"]["part"]["triangles"].erase(0);check(rejects(j),"open surface");j=demo;for(auto& t:j["mesh"]["part"]["triangles"])std::swap(t[0],t[1]);check(rejects(j),"inward surface");j=demo;j["mesh"]["part"]["points"][6]={0,0,0};check(rejects(j),"concave closed mesh blocked");j=demo;j["mesh"]["part"]["sensitive"]=false;check(rejects(j),"one sensitive body required");j=demo;j["transport_allowed"]=true;check(rejects(j),"input cannot set approval");j=demo;j["source"]["orbit"]="LEO";check(rejects(j),"unknown environment declaration");j=demo;j["mesh"]["part"]["points"].push_back({0,0,0});check(rejects(j),"unused point blocked");
    TriangleMesh tetra{{{0,0,0},{2,0,0},{0,2,0},{0,0,2}},{{0,2,1},{0,1,3},{0,3,2},{1,2,3}}};j=demo;j["mesh"]=makeTriangleMeshBundle(tetra,"Tetra","G4_Si",true,{0,0,0},{0,0,0},{{"kind","external_mesh"},{"description","synthetic tetra"}});check(parse(j).mesh.mesh.triangles.size()==4,"non-box convex solid allowed");j["solid"]="analytic_box_reference";check(rejects(j),"tetra cannot silently become box");
    auto bytes=QByteArray::fromStdString(demo.dump());bytes.replace("\"histories\":10000","\"histories\":10000,\"histories\":20000");bool bad=false;try{parseMeshExperiment(bytes);}catch(const std::exception&){bad=true;}check(bad,"duplicate job field");bad=false;try{Project::fromJson(demo);}catch(const std::exception&){bad=true;}check(bad,"experimental job cannot enter ordinary project parser");
    std::cout<<count<<" mesh experiment checks passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"Check "<<count<<": "<<e.what()<<'\n';return 1;}}
